     Ci.nsMsgFolderFlags.Drafts,
@@ -57,3 +70,46 @@ add_task(async function test_edit_draft_keeps_related_inline_pdf_attachment() {

   await close_compose_window(cwc);
 });
+
+add_task(async function test_edit_draft_keeps_referenced_related_attachments() {
+  const draftsFolder = await get_special_folder(
+    Ci.nsMsgFolderFlags.Drafts,
+    true
+  );
+  const file = new FileUtils.File(
+    getTestFilePath("../attachment/data/apple_mail_related_attachments.eml")
+  );
+  const source = await IOUtils.readUTF8(file.path);
+
+  draftsFolder.QueryInterface(Ci.nsIMsgLocalMailFolder).addMessage(source);
+
+  await be_in_folder(draftsFolder);
+  await make_display_unthreaded();
+
+  const draftMsg = await selectDraftBySubject(
+    "Apple Mail referenced related attachments"
+  );
+  await assert_selected_and_displayed(window, draftMsg);
+  await wait_for_notification_to_show(
+    get_about_message(),
+    "mail-notification-top",
+    "draftMsgContent"
+  );
+
+  const cwc = await open_compose_from_draft();
+  const bucket = cwc.document.getElementById("attachmentBucket");
+
+  Assert.equal(bucket.itemCount, 3, "The draft should restore all attachments");
+
+  const expectedNames = ["example.md", "example.sh", "example.py"];
+
+  for (const [i, expectedName] of expectedNames.entries()) {
+    Assert.equal(
+      bucket.itemChildren[i].attachment.name,
+      expectedName,
+      `attachment ${i + 1} should be ${expectedName}`
+    );
+  }
+
+  await close_compose_window(cwc);
+});
diff --git a/mailnews/mime/src/mimemrel.cpp b/mailnews/mime/src/mimemrel.cpp
index ce75e81812a..76af0f5c3d7 100644
--- a/mailnews/mime/src/mimemrel.cpp
+++ b/mailnews/mime/src/mimemrel.cpp
@@ -113,7 +113,6 @@
 #include "nsMimeTypes.h"
 #include "nsMsgUtils.h"
 #include "nsMsgCompUtils.h"
-#include <ctype.h>

 #define MIME_SUPERCLASS mimeMultipartClass
 MimeDefClass(MimeMultipartRelated, MimeMultipartRelatedClass,
@@ -832,6 +831,22 @@ static bool accept_related_part(MimeMultipartRelated* relobj,
           IS_SPACE(relobj->curtag[2]));
 }

+static bool hide_related_part_p(MimeMultipartRelated* relobj,
+                                MimeObject* part_obj) {
+  if (!relobj || !part_obj || relobj->is_part_in_hidden_alternative) {
+    return false;
+  }
+
+  // Surface named text/* parts as attachments even when CID-referenced;
+  // they are files the user needs, not inline body content.
+  char* name = MimeHeaders_get_name(part_obj->headers, part_obj->options);
+  bool hasName = name != nullptr;
+  PR_FREEIF(name);
+
+  return !(hasName && part_obj->content_type &&
+           !PL_strncasecmp(part_obj->content_type, "text/", 5));
+}
+
 static int flush_tag(MimeMultipartRelated* relobj) {
   int length = relobj->curtag_length;
   char* buf;
@@ -921,7 +936,7 @@ static int flush_tag(MimeMultipartRelated* relobj) {
           if (status < 0) return status;
           buf = ptr2; /* skip over the cid: URL we substituted */

-          if (!relobj->is_part_in_hidden_alternative && value->m_obj)
+          if (hide_related_part_p(relobj, value->m_obj))
             value->m_obj->dontShowAsAttachment = true;
         }

@@ -955,7 +970,7 @@ static int flush_tag(MimeMultipartRelated* relobj) {
           if (status < 0) return status;
           buf = ptr2; /* skip over the cid: URL we substituted */

-          if (!relobj->is_part_in_hidden_alternative && value->m_obj)
+          if (hide_related_part_p(relobj, value->m_obj))
             value->m_obj->dontShowAsAttachment = true;
         }
